	cols := []datatable.Column[workspaceRow]{col0(t)}
	for _, name := range []string{"devdesk", "clients", "notes.md"} {
		r := rowNamed(t, m, name)
		if got := cols[0].Indicator(r); got != indicator.Idle {
			t.Errorf("%s: Indicator = %v, want Idle", name, got)
