// indFixture is a catalog with one entry of each source kind. The names are
// sorted API, Img, Web.
func indFixture(t *testing.T) Model {
	t.Helper()
	t.Setenv("HOME", t.TempDir())
	t.Setenv("USERPROFILE", t.TempDir())
	api := entry("api", "API")
