	img := template.Entry{Slug: "img", Name: "Img", Source: template.Source{Kind: template.KindOCI, URL: "registry.example.com/", Path: "acme/img"}}
	m := opened(t, api, web, img)
	return send(t, m, testutil.Resize(120, 30))
