	}
	m = snapshot(t, m, []jobs.Run{indRun(jobs.KindSync, jobs.ItemDone, "api")}, nil)
	line := lineOf(t, m, "API")
	if !strings.Contains(line, kindGlyph(template.KindGit)) || hasAnyGlyph(line) {
